GENRE_EN = {"ラーメン":"Ramen","定食":"Set meals","お好み焼き・たこ焼き":"Okonomiyaki & takoyaki","カレー":"Curry","そば":"Soba","うどん":"Udon","学生食堂風定食":"Canteen-style set meals","回転寿司":"Conveyor-belt sushi","海鮮丼":"Seafood rice bowls","干物定食":"Dried-fish set meals","とんかつ":"Tonkatsu","喫茶・軽食":"Cafe & light meals","焼鳥・居酒屋":"Yakitori & izakaya","しゃぶしゃぶ":"Shabu-shabu","焼肉":"Yakiniku","イタリアン":"Italian","天ぷら":"Tempura","蕎麦会席":"Soba kaiseki","寿司":"Sushi","海鮮浜焼き":"Grilled seafood","和食ランチ":"Japanese lunch","洋食":"Western-style Japanese","鉄板焼":"Teppanyaki","中華":"Chinese","鮨":"Sushi (omakase)","割烹":"Kappo","フランス料理":"French","日本料理":"Japanese cuisine","ステーキ":"Steak","展望ダイニング":"Sky dining","会席":"Kaiseki","蟹料理":"Crab dishes","懐石":"Kaiseki","うなぎ":"Eel"}

def build():
    p = os.path.join(ROOT, 'data', 'sights.json')
    d = json.load(open(p, encoding='utf-8'))
    ids = {s['id'] for s in d}
    for s in NEW_SIGHTS:
        if s['id'] not in ids: d.append(s)
    json.dump(d, open(p, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    items = []
    for i, r in enumerate(R, 1):
        t, st, name, kana, genre, price, walk, addr, hours, closed, dish, zh, ja = r
        items.append({"id": "r%02d" % i, "tier": t, "station": st, "name": name, "kana": kana, "genre": genre, "genreEn": GENRE_EN.get(genre, ''),
                      "price": price, "walk": walk, "address": addr, "hours": hours, "closed": closed, "dish": dish, "zh": zh, "ja": ja})
    out = {"note": "店名、住所、價格、營業時間皆為虛構。", "tiers": TIERS,
           "stations": ["谷山","浦川","九里橋三丁目","東松沢","戸宮","花倉街道","大學前","みつせ","名島港","勝守","天鳥崎中央","東平倉","南九里","紫市"],
           "items": items}
    json.dump(out, open(os.path.join(ROOT, 'data', 'dining.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print('sights', len(d), 'dining', len(items))

if __name__ == '__main__': build()
